function when(ts){const d=Math.max(0,Date.now()/1000-ts);if(d<60)return L("à l'instant · 刚刚");if(d<3600)return L(Math.floor(d/60)+" min · "+Math.floor(d/60)+"分钟前");if(d<86400)return L(Math.floor(d/3600)+" h · "+Math.floor(d/3600)+"小时前");if(d<86400*30)return L(Math.floor(d/86400)+" j · "+Math.floor(d/86400)+"天前");return new Date(ts*1000).toLocaleDateString()}
