function fmt(t){const lines=esc(t).split("\n");let out="",ul=0;const close=()=>{if(ul){out+="</ul>";ul=0}};
  for(let l of lines){l=l.replace(/\*\*(.+?)\*\*/g,"<b>$1</b>");if(/^\s*[-•] /.test(l)){if(!ul){out+="<ul>";ul=1}out+="<li>"+l.replace(/^\s*[-•] /,"")+"</li>";continue}close();
    if(/^&gt; /.test(l))out+=`<div class="cm-tip">${l.slice(5)}</div>`;else if(/^# /.test(l))out+=`<h4>${l.slice(2)}</h4>`;else if(!l.trim())out+="<div style='height:6px'></div>";else out+=`<p>${l}</p>`}
  close();return out}
