   <div><label>${L("Frais couverts (une ligne : libellé | montant) · 费用明细")}</label><textarea id="dnc" rows="4" placeholder="Serveur (VPS) | ~6 €/mois&#10;Nom de domaine | ~12 €/an">${esc(DD.costs.map(c=>c.l+" | "+c.a).join("\n"))}</textarea></div>
